<?php
require_once __DIR__.'/../app/bootstrap.php';$a=admin_required($pdo);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$act=(string)($_POST['action']??'');
try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id,role,status FROM users WHERE id=? FOR UPDATE');$s->execute([$id]);$t=$s->fetch();if(!$t)throw new RuntimeException('Membre introuvable.');if((int)$t['id']===(int)$a['id'])throw new RuntimeException('Vous ne pouvez pas modifier votre propre compte.');
if($act==='activate'){$s=$pdo->prepare("SELECT status FROM activation_payments WHERE user_id=? FOR UPDATE");$s->execute([$id]);$p=$s->fetch();if(!$p||$p['status']!=='pending'||$t['status']!=='pending_payment')throw new RuntimeException('Ce compte n’est pas en attente de paiement.');$s=$pdo->prepare("UPDATE activation_payments SET status='verified',verified_by=?,verified_at=NOW() WHERE user_id=? AND status='pending'");$s->execute([$a['id'],$id]);if($s->rowCount()!==1)throw new RuntimeException('Paiement déjà traité.');$s=$pdo->prepare("UPDATE users SET status='active',payment_verified_at=NOW() WHERE id=? AND status='pending_payment'");$s->execute([$id]);log_admin($pdo,(int)$a['id'],'activate_after_manual_payment_check',(int)$id);$msg='Compte activé. Assurez-vous d’avoir vérifié le paiement dans Maketou.';}
elseif($act==='suspend'){$s=$pdo->prepare("UPDATE users SET status='suspended' WHERE id=? AND role='member'");$s->execute([$id]);log_admin($pdo,(int)$a['id'],'suspend_member',(int)$id);$msg='Compte suspendu.';}
elseif($act==='unsuspend'){$s=$pdo->prepare("UPDATE users SET status='active' WHERE id=? AND role='member' AND status='suspended' AND payment_verified_at IS NOT NULL");$s->execute([$id]);if($s->rowCount()!==1)throw new RuntimeException('Réactivation impossible.');log_admin($pdo,(int)$a['id'],'unsuspend_member',(int)$id);$msg='Compte réactivé.';}
else throw new RuntimeException('Action invalide.');$pdo->commit();flash('success',$msg);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'Opération impossible.');if(!($e instanceof RuntimeException))error_log($e->getMessage());}go('admin.php');}
$f=(string)($_GET['status']??'pending_payment');if(!in_array($f,['pending_payment','active','suspended','all'],true))$f='pending_payment';
$sql='SELECT u.*,p.status pay_status,p.amount,p.provider_reference FROM users u LEFT JOIN activation_payments p ON p.user_id=u.id';$args=[];if($f!=='all'){$sql.=' WHERE u.status=?';$args[]=$f;}$sql.=' ORDER BY u.created_at DESC LIMIT 300';$s=$pdo->prepare($sql);$s->execute($args);$members=$s->fetchAll();$stats=$pdo->query("SELECT COUNT(*) total,SUM(status='pending_payment') pending,SUM(status='active') active FROM users WHERE role='member'")->fetch();
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administration — InvestiCash</title><link rel="stylesheet" href="assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">IC</span> InvestiCash</a><nav><a href="dashboard.php">Espace membre</a><a href="logout.php">Déconnexion</a></nav></header><main class="container page"><span class="eyebrow">CONSOLE ADMINISTRATEUR</span><h1>Administration</h1><p class="muted">Connecté : <?=e($a['email'])?>. Vérifiez les paiements dans le compte marchand avant toute activation.</p><?php foreach(flashes() as [$t,$m]):?><div class="alert <?=e($t)?>"><?=e($m)?></div><?php endforeach;?><div class="stats"><article class="stat"><small>Membres</small><b><?=(int)$stats['total']?></b></article><article class="stat"><small>En attente</small><b><?=(int)$stats['pending']?></b></article><article class="stat"><small>Actifs</small><b><?=(int)$stats['active']?></b></article></div><section class="glass panel"><form class="filter" method="get"><select name="status"><option value="pending_payment" <?=$f==='pending_payment'?'selected':''?>>En attente</option><option value="active" <?=$f==='active'?'selected':''?>>Actifs</option><option value="suspended" <?=$f==='suspended'?'selected':''?>>Suspendus</option><option value="all" <?=$f==='all'?'selected':''?>>Tous</option></select><button class="btn btn-small">Filtrer</button></form><div class="tablewrap"><table><thead><tr><th>Membre</th><th>Inscription</th><th>Statut</th><th>Paiement</th><th>Actions</th></tr></thead><tbody><?php foreach($members as $m):?><tr><td><b><?=e($m['name'])?></b><span class="small"><?=e($m['email'])?></span><span class="small">Code : <?=e($m['referral_code'])?></span></td><td><?=e($m['created_at'])?></td><td><?=e($m['status'])?></td><td><?=($m['pay_status']??'')==='verified'?'Vérifié':'À vérifier'?><span class="small"><?=e($m['provider_reference']??'Aucune référence')?></span></td><td><div class="admin-action"><?php if($m['status']==='pending_payment'&&($m['pay_status']??'')==='pending'):?><form method="post" onsubmit="return confirm('Avez-vous vérifié la transaction dans Maketou ?');"><?=csrf()?><input type="hidden" name="id" value="<?=(int)$m['id']?>"><input type="hidden" name="action" value="activate"><button class="btn btn-small">Paiement vérifié : activer</button></form><?php elseif($m['status']==='active'&&$m['role']==='member'):?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=(int)$m['id']?>"><input type="hidden" name="action" value="suspend"><button class="btn btn-small">Suspendre</button></form><?php elseif($m['status']==='suspended'):?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=(int)$m['id']?>"><input type="hidden" name="action" value="unsuspend"><button class="btn btn-small">Réactiver</button></form><?php else:?>—<?php endif;?></div></td></tr><?php endforeach;?><?php if(!$members):?><tr><td colspan="5">Aucun membre trouvé.</td></tr><?php endif;?></tbody></table></div></section><div class="notice">Important : cette version ne reçoit pas de webhook Maketou. L'activation manuelle doit être effectuée uniquement après vérification indépendante du paiement.</div><footer class="footer"><span>© <?=date('Y')?> InvestiCash</span></footer></main></body></html>
